// A tiny, dependency-free bundler for the custom-functions script.
//
// Why this exists in a build-free project: Excel for Mac evaluates the
// manifest's custom-functions <Script> as a CLASSIC script. An ES module there
// (anything with `import`) is a syntax error, the runtime never starts, and
// every TB.* formula sits at #BUSY! forever with no error anywhere. So the
// functions entry point and everything it imports are flattened into one
// classic script. The task pane is unaffected and still loads plain modules.
//
// Scope: exactly the module shapes this repo uses -- relative named imports
// (`import { a, b as c } from "./x.js"`) and named exports (`export function`,
// `export async function`, `export const/let/class`). Anything else (default
// exports, `export *`, bare-specifier imports) is refused loudly rather than
// bundled wrong.
//
// Each module becomes an IIFE returning its exports, so helper names in
// different modules cannot collide.

import fs from "node:fs";
import path from "node:path";

const IMPORT_RE = /^\s*import\s*\{([^}]*)\}\s*from\s*["']([^"']+)["'];?[ \t]*$/gm;
const EXPORT_DECL_RE = /^export\s+(async\s+function\*?|function\*?|const|let|var|class)\s+([A-Za-z_$][\w$]*)/gm;

function parseModule(file) {
  const src = fs.readFileSync(file, "utf8");

  if (/^\s*export\s+(default|\*|\{)/m.test(src)) {
    throw new Error(`${file}: only named declaration exports are supported by tools/bundle.js`);
  }
  const strayImport = src.match(/^\s*import\s+(?!\{)[^\n]*$/m);
  if (strayImport) throw new Error(`${file}: unsupported import form: ${strayImport[0].trim()}`);

  const imports = [];
  for (const m of src.matchAll(IMPORT_RE)) {
    const spec = m[2];
    if (!spec.startsWith(".")) throw new Error(`${file}: bare import "${spec}" is not supported`);
    const bindings = m[1]
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => {
        const [imported, local] = s.split(/\s+as\s+/).map((x) => x.trim());
        return { imported, local: local ?? imported };
      });
    imports.push({ statement: m[0], dep: path.resolve(path.dirname(file), spec), bindings });
  }

  const exportsList = [...src.matchAll(EXPORT_DECL_RE)].map((m) => m[2]);
  return { file, src, imports, exportsList };
}

/** Bundle `entry` and its relative imports into one classic-script string. */
export function bundle(entry) {
  const modules = new Map();
  const order = [];

  const visit = (file, stack = []) => {
    if (modules.has(file)) return;
    if (stack.includes(file)) throw new Error(`import cycle: ${[...stack, file].join(" -> ")}`);
    const mod = parseModule(file);
    for (const imp of mod.imports) visit(imp.dep, [...stack, file]);
    modules.set(file, mod);
    order.push(file);
  };
  visit(path.resolve(entry));

  const ids = new Map(order.map((f, i) => [f, `__mod${i}`]));
  const root = path.dirname(path.resolve(entry));

  const parts = order.map((file) => {
    const mod = modules.get(file);
    let body = mod.src;
    for (const imp of mod.imports) {
      const depMod = modules.get(imp.dep);
      for (const b of imp.bindings) {
        if (!depMod.exportsList.includes(b.imported)) {
          throw new Error(`${file}: "${b.imported}" is not exported by ${imp.dep}`);
        }
      }
      const destructure = imp.bindings
        .map((b) => (b.imported === b.local ? b.local : `${b.imported}: ${b.local}`))
        .join(", ");
      body = body.replace(imp.statement, `const { ${destructure} } = ${ids.get(imp.dep)};`);
    }
    body = body.replace(/^export\s+(?=(async\s+function|function|const|let|var|class)\b)/gm, "");
    const rel = path.relative(root, file);
    return (
      `// ---- ${rel} ----\n` +
      `const ${ids.get(file)} = (() => {\n${body}\nreturn { ${mod.exportsList.join(", ")} };\n})();\n`
    );
  });

  return (
    `// GENERATED by tools/bundle.js from ${path.relative(process.cwd(), entry)} -- do not edit.\n` +
    `// A classic script: Excel for Mac does not load the custom-functions <Script> as a module.\n` +
    `(() => {\n"use strict";\n${parts.join("\n")}})();\n`
  );
}

// CLI: node tools/bundle.js <entry> [out]
if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname)) {
  const [entry, out] = process.argv.slice(2);
  if (!entry) {
    console.error("Usage: node tools/bundle.js <entry.js> [out.js]");
    process.exit(1);
  }
  const code = bundle(entry);
  if (out) fs.writeFileSync(out, code);
  else process.stdout.write(code);
}
